import { defineConfig, devices } from "@playwright/test";
import path from "node:path";

// CHROMIUM_PATH lets you point at an existing Chromium when Playwright's own download is unavailable.
const executablePath = process.env.CHROMIUM_PATH || undefined;
const launchOptions = {
  executablePath,
  args: ["--no-sandbox", "--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream",
    // The fake microphone "hums" the first two bars of the demo tune (generated by backend/tests/audio_synth.py).
    `--use-file-for-fake-audio-capture=${path.resolve(__dirname, "e2e/fixtures/demo-hum.wav")}`, "--autoplay-policy=no-user-gesture-required"],
};

export default defineConfig({
  testDir: "./e2e",
  timeout: 90_000,
  retries: 0,
  use: { baseURL: process.env.E2E_BASE_URL ?? "http://localhost:3000", trace: "off", launchOptions },
  projects: [
    { name: "desktop", use: { ...devices["Desktop Chrome"], launchOptions } },
    { name: "mobile", use: { ...devices["Pixel 7"], launchOptions } },
  ],
});
